const releaseDueReviews = `-- name: ReleaseDueReviews :many
UPDATE reviews SET released = true WHERE NOT released AND visible_at <= $1 RETURNING from_id, to_id
`

type ReleaseDueReviewsRow struct {
	FromID string
	ToID   string
}

func (q *Queries) ReleaseDueReviews(ctx context.Context, now time.Time) ([]ReleaseDueReviewsRow, error) {
	rows, err := q.db.Query(ctx, releaseDueReviews, now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReleaseDueReviewsRow{}
	for rows.Next() {
		var i ReleaseDueReviewsRow
		if err := rows.Scan(&i.FromID, &i.ToID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const releaseReviewsOfBooking = `-- name: ReleaseReviewsOfBooking :exec
UPDATE reviews SET visible_at = LEAST(visible_at, $1), released = true WHERE booking_id = $2
`

type ReleaseReviewsOfBookingParams struct {
	Now       time.Time
	BookingID string
}

// Both parties reviewed: show both now.
func (q *Queries) ReleaseReviewsOfBooking(ctx context.Context, arg ReleaseReviewsOfBookingParams) error {
	_, err := q.db.Exec(ctx, releaseReviewsOfBooking, arg.Now, arg.BookingID)
	return err
}

const reviewExists = `-- name: ReviewExists :one
SELECT EXISTS (SELECT 1 FROM reviews WHERE booking_id = $1 AND from_id = $2)
`

type ReviewExistsParams struct {
	BookingID string
	FromID    string
}

func (q *Queries) ReviewExists(ctx context.Context, arg ReviewExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, reviewExists, arg.BookingID, arg.FromID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const updateBooking = `-- name: UpdateBooking :exec
UPDATE bookings SET status = $1, overdue = $2, accepted_at = $3, declined_at = $4,
  decline_reason = $5, cancelled_at = $6, cancelled_by = $7,
  cancel_reason = $8, active_at = $9, returned_at = $10, completed_at = $11,
  completed_auto = $12, resolved_at = $13, renter_agreed_at = $14,
  provider_agreed_at = $15, payment = $16, meeting_point_detail = $17,
  checkout = $18, checkin = $19, collateral_return = $20, dispute_id = $21,
  updated_at = now()
WHERE id = $22
`

type UpdateBookingParams struct {
	Status             string
	Overdue            bool
	AcceptedAt         *time.Time
	DeclinedAt         *time.Time
	DeclineReason      *string
	CancelledAt        *time.Time
	CancelledBy        *string
	CancelReason       *string
	ActiveAt           *time.Time
	ReturnedAt         *time.Time
	CompletedAt        *time.Time
	CompletedAuto      *bool
	ResolvedAt         *time.Time
	RenterAgreedAt     *time.Time
	ProviderAgreedAt   *time.Time
	Payment            domain.PaymentInfo
	MeetingPointDetail *string
	Checkout           *domain.Checkout
	Checkin            *domain.Checkin
	CollateralReturn   *domain.CollateralReturn
	DisputeID          *string
	ID                 string
}

func (q *Queries) UpdateBooking(ctx context.Context, arg UpdateBookingParams) error {
	_, err := q.db.Exec(ctx, updateBooking,
		arg.Status,
		arg.Overdue,
		arg.AcceptedAt,
		arg.DeclinedAt,
		arg.DeclineReason,
		arg.CancelledAt,
		arg.CancelledBy,
		arg.CancelReason,
		arg.ActiveAt,
		arg.ReturnedAt,
		arg.CompletedAt,
		arg.CompletedAuto,
		arg.ResolvedAt,
		arg.RenterAgreedAt,
		arg.ProviderAgreedAt,
		arg.Payment,
		arg.MeetingPointDetail,
		arg.Checkout,
		arg.Checkin,
		arg.CollateralReturn,
		arg.DisputeID,
		arg.ID,
	)
	return err
}

const upsertChatRead = `-- name: UpsertChatRead :exec
INSERT INTO chat_reads (user_id, booking_id, read_at) VALUES ($1, $2, $3)
ON CONFLICT (user_id, booking_id) DO UPDATE SET read_at = EXCLUDED.read_at
`

type UpsertChatReadParams struct {
	UserID    string
	BookingID string
	ReadAt    time.Time
}

func (q *Queries) UpsertChatRead(ctx context.Context, arg UpsertChatReadParams) error {
	_, err := q.db.Exec(ctx, upsertChatRead, arg.UserID, arg.BookingID, arg.ReadAt)
	return err
}
